from scipy import stats

def find_mode(L):
    def flatten(nested):
        for item in nested:
            if isinstance(item, list):
                yield from flatten(item)
            else:
                yield item

    flattened = list(flatten(L))
    arr = np.array(flattened)
    mode_result = stats.mode(arr)
    return int(mode_result.mode[0])

