from scipy import stats

def mode(L):
    # Flatten the nested list
    flat = []
    for item in L:
        if isinstance(item, list):
            flat.extend(mode(item))
        else:
            flat.append(item)
    # Compute and return the mode
    return stats.mode(flat)[0][0]

